## Route Handlers

Route Handlers allow you to create custom request handlers for a given route using the Web [Request](https://developer.mozilla.org/docs/Web/API/Request) and [Response](https://developer.mozilla.org/docs/Web/API/Response) APIs.

<Image
  alt="Route.js Special File"
  srcLight="/docs/light/route-special-file.png"
  srcDark="/docs/dark/route-special-file.png"
  width="1600"
  height="444"
/>

> **Good to know**: Route Handlers are only available inside the `app` directory. They are the equivalent of [API Routes](/docs/pages/building-your-application/routing/api-routes) inside the `pages` directory meaning you **do not** need to use API Routes and Route Handlers together.

### Convention

Route Handlers are defined in a [`route.js|ts` file](/docs/app/api-reference/file-conventions/route) inside the `app` directory:

```ts filename="app/api/route.ts" switcher
export async function GET(request: Request) {}
```

```js filename="app/api/route.js" switcher
export async function GET(request) {}
```

Route Handlers can be nested anywhere inside the `app` directory, similar to `page.js` and `layout.js`. But there **cannot** be a `route.js` file at the same route segment level as `page.js`.

### Supported HTTP Methods

The following [HTTP methods](https://developer.mozilla.org/docs/Web/HTTP/Methods) are supported: `GET`, `POST`, `PUT`, `PATCH`, `DELETE`, `HEAD`, and `OPTIONS`. If an unsupported method is called, Next.js will return a `405 Method Not Allowed` response.

### Extended `NextRequest` and `NextResponse` APIs

In addition to supporting the native [Request](https://developer.mozilla.org/docs/Web/API/Request) and [Response](https://developer.mozilla.org/docs/Web/API/Response) APIs, Next.js extends them with [`NextRequest`](/docs/app/api-reference/functions/next-request) and [`NextResponse`](/docs/app/api-reference/functions/next-response) to provide convenient helpers for advanced use cases.

### Caching

Route Handlers are not cached by default. You can, however, opt into caching for `GET` methods. Other supported HTTP methods are **not** cached. To cache a `GET` method, use a [route config option](/docs/app/guides/caching-without-cache-components#dynamic) such as `export const dynamic = 'force-static'` in your Route Handler file.

```ts filename="app/items/route.ts" switcher
export const dynamic = 'force-static'

export async function GET() {
  const res = await fetch('https://data.mongodb-api.com/...', {
    headers: {
      'Content-Type': 'application/json',
      'API-Key': process.env.DATA_API_KEY,
    },
  })
  const data = await res.json()

  return Response.json({ data })
}
```

```js filename="app/items/route.js" switcher
export const dynamic = 'force-static'

export async function GET() {
  const res = await fetch('https://data.mongodb-api.com/...', {
    headers: {
      'Content-Type': 'application/json',
      'API-Key': process.env.DATA_API_KEY,
    },
  })
  const data = await res.json()

  return Response.json({ data })
}
```

> **Good to know**: Other supported HTTP methods are **not** cached, even if they are placed alongside a `GET` method that is cached, in the same file.

#### With Cache Components

When [Cache Components](/docs/app/getting-started/caching) is enabled, `GET` Route Handlers follow the same model as normal UI routes in your application. They run at request time by default, can be prerendered when they don't access uncached or runtime data, and you can use `use cache` to include uncached data in the static response.

**Static example** - doesn't access uncached or runtime data, so it will be prerendered at build time:

```tsx filename="app/api/project-info/route.ts"
export async function GET() {
  return Response.json({
    projectName: 'Next.js',
  })
}
```

**Dynamic example** - accesses non-deterministic operations. During the build, prerendering stops when `Math.random()` is called, deferring to request-time rendering:

```tsx filename="app/api/random-number/route.ts"
export async function GET() {
  return Response.json({
    randomNumber: Math.random(),
  })
}
```

import type { CharacterCard, LogEntry, Mode, SpokenSegment, StoryDef, StoryState } from "@/lib/types";
import type { Turn } from "@/lib/engine/schema";
import { normalizeVoice, pickUnusedVoice } from "@/lib/voices";

const MAX_NOTES = 30;
const MAX_OBJECTS = 20;
const MAX_CHARACTERS = 12;

export function initialState(story: StoryDef, mode: Mode): StoryState {
  return {
    story,
    mode,
    beatIndex: 0,
    turnsInBeat: 0,
    characters: story.characters.map((c) => ({ ...c })),
    objects: [],
    plotNotes: [],
    log: [],
    ended: false,
  };
}

export function slugify(name: string): string {
  return (
    name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 40) || "friend"
  );
}

export function findCharacter(characters: CharacterCard[], speaker: string): CharacterCard | undefined {
  const s = speaker.trim().toLowerCase();
  if (!s || s === "narrator") return undefined;
  return (
    characters.find((c) => c.id === s) ??
    characters.find((c) => c.name.toLowerCase() === s) ??
    characters.find((c) => slugify(c.name) === slugify(s)) ??
    characters.find((c) => c.name.toLowerCase().includes(s) || s.includes(c.name.toLowerCase()))
  );
}

export function addChildUtterance(state: StoryState, text: string): StoryState {
  const entry: LogEntry = { kind: "child", speaker: "child", text, beatIndex: state.beatIndex };
  return { ...state, log: [...state.log, entry] };
}

function mergeCharacters(state: StoryState, turn: Turn): CharacterCard[] {
  const characters = [...state.characters];
  for (const add of turn.stateChanges.addCharacters ?? []) {
    if (characters.length >= MAX_CHARACTERS) break;
    if (findCharacter(characters, add.name)) continue;
    let id = slugify(add.name);
    while (characters.some((c) => c.id === id)) id += "-2";
    const used = [state.story.narratorVoice, ...characters.map((c) => c.voice)].map((v) => normalizeVoice(v) ?? v);
    const requested = normalizeVoice(add.voice);
    const voice = requested && !used.includes(requested) ? requested : pickUnusedVoice(used);
    characters.push({ id, name: add.name, personality: add.personality, look: add.look, voice, invented: true });
  }
  return characters;
}

function dedupe(list: string[], max: number): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const item of list) {
    const key = item.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out.slice(-max);
}

export interface AppliedTurn {
  state: StoryState;
  spoken: SpokenSegment[];
}

export function applyTurn(state: StoryState, turn: Turn): AppliedTurn {
  const characters = mergeCharacters(state, turn);
  const lastBeat = state.story.beats.length - 1;

  const spoken: SpokenSegment[] = turn.segments.map((seg) => {
    const ch = findCharacter(characters, seg.speaker);
    return ch
      ? { speakerId: ch.id, speakerName: ch.name, voice: ch.voice, text: seg.text }
      : { speakerId: "narrator", speakerName: "Narrator", voice: state.story.narratorVoice, text: seg.text };
  });

  const newEntries: LogEntry[] = spoken.map((s) => ({
    kind: s.speakerId === "narrator" ? "narration" : "dialogue",
    speaker: s.speakerName,
    text: s.text,
    beatIndex: state.beatIndex,
  }));

  const ended = turn.isEnding && state.beatIndex >= lastBeat;
  const advance = turn.advanceBeat && state.beatIndex < lastBeat;

  return {
    spoken,
    state: {
      ...state,
      characters,
      objects: dedupe([...state.objects, ...(turn.stateChanges.addObjects ?? [])], MAX_OBJECTS),
      plotNotes: dedupe([...state.plotNotes, ...(turn.stateChanges.plotNotes ?? [])], MAX_NOTES),
      log: [...state.log, ...newEntries],
      beatIndex: advance ? state.beatIndex + 1 : state.beatIndex,
      turnsInBeat: advance ? 0 : state.turnsInBeat + 1,
      ended,
    },
  };
}
export type Category = "fairy-tale" | "bible" | "fable" | "custom";

export interface CharacterCard {
  id: string;
  name: string;
  personality: string;
  look: string;
  voice: string;
  invented?: boolean;
}

export interface Beat {
  title: string;
  goal: string;
}

export interface StoryDef {
  id: string;
  title: string;
  emoji: string;
  blurb: string;
  category: Category;
  setting: string;
  artStyle: string;
  narratorVoice: string;
  characters: CharacterCard[];
  beats: Beat[];
}

export type LogKind = "narration" | "dialogue" | "child";

export interface LogEntry {
  kind: LogKind;
  speaker: string;
  text: string;
  beatIndex: number;
}

export type Mode = "listen" | "play";

export interface StoryState {
  story: StoryDef;
  mode: Mode;
  beatIndex: number;
  turnsInBeat: number;
  characters: CharacterCard[];
  objects: string[];
  plotNotes: string[];
  log: LogEntry[];
  ended: boolean;
}

export interface SpokenSegment {
  speakerId: string;
  speakerName: string;
  voice: string;
  text: string;
}
