import type { StoryDef } from "@/lib/types";

/** These files are generated once and shipped with the four built-in books. */
const PAGE_COUNTS: Record<string, number> = {
  "noahs-ark": 6,
  "three-little-pigs": 5,
  "tortoise-and-hare": 5,
  "little-red-riding-hood": 5,
};

export function standardArtUrl(story: StoryDef, beatIndex: number): string | undefined {
  const count = PAGE_COUNTS[story.id];
  if (story.category === "custom" || count === undefined || !Number.isInteger(beatIndex) || beatIndex < 0 || beatIndex >= count) return;
  return `/story-art/${story.id}/beat-${beatIndex}.jpg`;
}

export function isStandardArtUrl(url: string): boolean {
  return Object.entries(PAGE_COUNTS).some(([id, count]) =>
    Array.from({ length: count }, (_, index) => `/story-art/${id}/beat-${index}.jpg`).includes(url));
}

/** Generate the built-in books' illustrations once, then commit the resulting JPEGs. */
const fs = require("node:fs/promises");
const path = require("node:path");
const ts = require("typescript");
const scenes = require("./story-art-scenes.json");

async function stories() {
  const source = await fs.readFile(path.join(__dirname, "../lib/stories/index.ts"), "utf8");
  const js = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText;
  const mod = { exports: {} };
  new Function("require", "module", "exports", js)(() => ({ voiceModel: name => name }), mod, mod.exports);
  return mod.exports.CLASSIC_STORIES;
}

async function generate(endpoint, input) {
  const response = await fetch(`https://fal.run/${endpoint}`, {
    method: "POST",
    headers: { Authorization: `Key ${process.env.FAL_KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify(input),
  });
  if (!response.ok) throw new Error(`${endpoint}: ${response.status} ${(await response.text()).slice(0, 240)}`);
  const result = await response.json();
  if (result.has_nsfw_concepts?.[0]) throw new Error(`${endpoint}: image blocked by safety checker`);
  const url = result.images?.[0]?.url;
  if (!url) throw new Error(`${endpoint}: no image returned`);
  const image = await fetch(url);
  if (!image.ok || !image.headers.get("content-type")?.startsWith("image/jpeg")) throw new Error(`${endpoint}: invalid JPEG output`);
  return { url, bytes: Buffer.from(await image.arrayBuffer()) };
}

async function main() {
  if (!process.env.FAL_KEY) throw new Error("Set FAL_KEY before generating story art.");
  const force = process.argv.includes("--force");
  for (const story of await stories()) {
    const bookScenes = scenes[story.id];
    if (!bookScenes || bookScenes.length !== story.beats.length) throw new Error(`Missing scenes for ${story.id}`);
    let reference;
    for (const [index, scene] of bookScenes.entries()) {
      const file = path.join(__dirname, "../public/story-art", story.id, `beat-${index}.jpg`);
      if (!force && await fs.stat(file).then(() => true, () => false)) {
        // Existing files are stable. A partial run can be resumed without charging again.
        console.log(`Keeping ${story.id} beat ${index}`);
        continue;
      }
      const looks = story.characters.map(character => `${character.name}: ${character.look}`).join("; ");
      const prompt = `${story.artStyle}. A single wide 4:3 storybook page, no panels. ${scene} Character designs: ${looks}. No words, letters, captions or signatures.`;
      const image = reference
        ? await generate("fal-ai/flux-kontext/dev", {
          prompt: `Keep the same watercolor style and established character designs from the reference image. Draw a different story moment: ${prompt}`,
          image_url: reference, resolution_mode: "4:3", num_inference_steps: 20,
          enable_safety_checker: true, output_format: "jpeg", seed: 44000 + index,
        })
        : await generate("fal-ai/flux/schnell", {
          prompt, image_size: "landscape_4_3", num_inference_steps: 4,
          num_images: 1, enable_safety_checker: true, output_format: "jpeg", seed: 44000,
        });
      await fs.mkdir(path.dirname(file), { recursive: true });
      await fs.writeFile(file, image.bytes);
      reference = image.url;
      console.log(`Saved ${story.id} beat ${index} (${image.bytes.length} bytes)`);
    }
  }
}

main().catch(error => { console.error(error); process.exitCode = 1; });

